    fallback: Any,
    message: str = "Operation failed",
    log_level: str = "warning",
    silent_exceptions: tuple[type[BaseException], ...] = (),
) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    """Decorator factory that guards a function against exceptions.

    Any exception raised by the wrapped function is caught and the configured
    ``fallback`` value is returned instead. Exceptions whose type is listed in
    ``silent_exceptions`` are swallowed without any logging. All other
    exceptions are logged via ``getattr(LOGGER, log_level)(message,
    exc_info=True)`` when ``message`` is provided.

    Args:
        fallback: Value returned when the wrapped function raises.
        message: Log message. When falsy, no logging is performed.
        log_level: Logger method to call ("debug", "info", "warning", "error").
        silent_exceptions: Exception types to swallow without logging.
    """

    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            try:
                return func(*args, **kwargs)
            except silent_exceptions:
                return fallback
            except Exception:
                if message:
                    getattr(LOGGER, log_level)(message, exc_info=True)
                return fallback

        return wrapper

    return decorator


